SELECT fn_cp_import_case('routier-accident-implique-un-collegue', '{"slug": "routier-accident-implique-un-collegue", "title": "Le conducteur du véhicule est un policier de votre commissariat", "theme_slug": "circulation", "difficulty": "difficile", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 30, "situation_text": "Il est 14 heures. Vous êtes appelée pour un accident matériel à un carrefour et découvrez, en arrivant sur place, que le conducteur de l''un des deux véhicules impliqués est un policier de votre propre commissariat, que vous connaissez personnellement pour avoir déjà travaillé avec lui à plusieurs reprises. L''autre conducteur, une automobiliste ordinaire, ignore ce lien professionnel entre vous et attend simplement un traitement impartial de cet accident.\n\nCe collègue, visiblement mal à l''aise de cette coïncidence, ne cherche pas explicitement à influencer votre constat, mais votre lien professionnel préexistant crée objectivement une situation de conflit d''intérêts potentiel, même en l''absence de toute pression exercée de sa part.\n\nCette situation, qui pourrait rester invisible pour l''automobiliste si vous ne la signaliez pas vous-même, pose la question de l''impartialité réelle et perçue de votre intervention dans un contexte où votre objectivité pourrait légitimement être questionnée si ce lien venait à être découvert ultérieurement.", "questions": [{"position": 1, "max_points": 5, "label": "Comment réagissez-vous en découvrant que le conducteur de l''un des véhicules est un collègue de votre commissariat ?", "hint": "La reconnaissance immédiate de ce conflit d''intérêts potentiel doit primer sur la tentation de simplement poursuivre l''intervention comme si de rien n''était.", "perfect": "Je reconnais immédiatement ce conflit d''intérêts potentiel, ce lien professionnel préexistant avec l''un des conducteurs créant objectivement une situation qui pourrait affecter, ou du moins faire suspecter, mon impartialité dans le traitement de cet accident.\n\nJe ne minimise pas cette situation au seul motif que mon collègue ne cherche pas explicitement à m''influencer, cette absence de pression directe ne suffisant pas à écarter le problème structurel que pose ce lien préexistant.\n\nJe reste attentive au fait que cette situation pourrait rester invisible pour l''autre conductrice si je ne la signalais pas moi-même, cette transparence étant nécessaire pour garantir l''intégrité réelle et perçue de mon intervention.\n\nJe considère qu''il m''appartient de gérer cette situation de manière proactive plutôt que d''attendre qu''elle soit découverte ultérieurement, cette anticipation étant essentielle pour préserver la confiance dans le traitement de cette affaire.", "points": [{"position": 1, "label": "Reconnaître immédiatement ce conflit d''intérêts potentiel", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : lien professionnel créant objectivement un problème.", "groups": [{"position": 1, "keywords": ["conflit d''intérêts reconnu", "lien professionnel", "objectivement problématique"]}]}, {"position": 2, "label": "Ne pas minimiser malgré l''absence de pression explicite du collègue", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Absence de pression ne suffisant pas à écarter le problème structurel.", "groups": [{"position": 1, "keywords": ["pas minimisé", "absence de pression insuffisante", "problème structurel"]}]}, {"position": 3, "label": "Rester attentive à ce que cette situation pourrait rester invisible sans transparence", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Transparence nécessaire pour l''intégrité perçue.", "groups": [{"position": 1, "keywords": ["situation invisible sans signalement", "transparence nécessaire", "intégrité perçue"]}]}, {"position": 4, "label": "Gérer la situation de manière proactive plutôt que passive", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Anticipation préservant la confiance dans le traitement.", "groups": [{"position": 1, "keywords": ["gestion proactive", "anticipation", "confiance préservée"]}]}]}, {"position": 2, "max_points": 5, "label": "Quelle décision concrète prenez-vous face à ce conflit d''intérêts identifié ?", "hint": "La solution la plus adaptée consiste généralement à se déporter de ce dossier plutôt qu''à tenter de gérer soi-même ce conflit d''intérêts.", "perfect": "Je me déporte de ce dossier en sollicitant l''intervention d''un autre équipage ou d''un collègue n''ayant aucun lien avec la personne impliquée, cette solution étant la plus adaptée pour garantir une impartialité incontestable.\n\nJe communique clairement les raisons de ce déport à ma hiérarchie, cette transparence institutionnelle étant nécessaire pour que la décision soit comprise et validée dans le cadre normal de fonctionnement du service.\n\nJe reste factuelle et neutre dans l''attente de ce remplacement, sans pour autant abandonner les mesures de sécurité immédiates nécessaires sur les lieux de l''accident avant l''arrivée de l''équipage remplaçant.\n\nJe n''informe pas nécessairement l''automobiliste des détails de cette situation, mais je m''assure que le traitement de son dossier soit repris par une personne dont l''impartialité ne pourra pas être questionnée.", "points": [{"position": 1, "label": "Se déporter du dossier en sollicitant un autre équipage", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : solution garantissant une impartialité incontestable.", "groups": [{"position": 1, "keywords": ["déport du dossier", "autre équipage", "impartialité incontestable"]}]}, {"position": 2, "label": "Communiquer clairement les raisons du déport à la hiérarchie", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Transparence institutionnelle nécessaire.", "groups": [{"position": 1, "keywords": ["raisons communiquées", "hiérarchie informée", "transparence institutionnelle"]}]}, {"position": 3, "label": "Rester factuelle et neutre en attendant le remplacement", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Maintien des mesures de sécurité immédiates.", "groups": [{"position": 1, "keywords": ["factuelle en attendant", "mesures de sécurité", "avant remplacement"]}]}, {"position": 4, "label": "S''assurer que le dossier soit repris par une personne impartiale", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Sans nécessairement informer l''automobiliste des détails.", "groups": [{"position": 1, "keywords": ["reprise impartiale", "pas de détails à l''automobiliste", "impartialité garantie"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment gérez-vous votre relation avec ce collègue impliqué dans l''accident, tout au long de cette intervention ?", "hint": "Le maintien d''une posture strictement professionnelle envers ce collègue est essentiel, indépendamment de la relation personnelle préexistante.", "perfect": "Je maintiens une posture strictement professionnelle envers ce collègue tout au long de cette intervention, sans que notre relation préexistante ne transparaisse dans le traitement de cette situation.\n\nJe reste attentive à ne pas lui accorder, même involontairement, un traitement différent de celui que j''appliquerais à n''importe quel autre conducteur impliqué dans un accident similaire.\n\nJe communique avec lui de manière transparente sur la nécessité de ce déport, cette explication pouvant contribuer à ce qu''il comprenne et accepte cette décision sans la percevoir comme une marque de défiance personnelle.\n\nJe reste consciente que cette situation, bien que délicate sur le plan relationnel, doit être gérée avec la même rigueur professionnelle que j''appliquerais à toute autre situation de conflit d''intérêts potentiel.", "points": [{"position": 1, "label": "Maintenir une posture strictement professionnelle envers le collègue", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : relation préexistante ne transparaissant pas.", "groups": [{"position": 1, "keywords": ["posture professionnelle", "relation préexistante non visible", "traitement neutre"]}]}, {"position": 2, "label": "Ne pas lui accorder un traitement différent même involontairement", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Même traitement que tout autre conducteur.", "groups": [{"position": 1, "keywords": ["pas de traitement différent", "même que tout conducteur", "vigilance involontaire"]}]}, {"position": 3, "label": "Communiquer avec transparence sur la nécessité du déport", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Compréhension sans perception de défiance personnelle.", "groups": [{"position": 1, "keywords": ["transparence sur le déport", "compréhension du collègue", "pas de défiance perçue"]}]}, {"position": 4, "label": "Gérer avec la même rigueur professionnelle que tout conflit d''intérêts", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Malgré la dimension relationnelle délicate.", "groups": [{"position": 1, "keywords": ["rigueur professionnelle", "malgré la dimension délicate", "même traitement du conflit"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('routier-trottinette-electrique-debridee', '{"slug": "routier-trottinette-electrique-debridee", "title": "L''engin dépasse largement la vitesse autorisée", "theme_slug": "circulation", "difficulty": "facile", "is_free": true, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 20, "situation_text": "Il est 17 h 30. Vous contrôlez, sur une voie urbaine, un utilisateur de trottinette électrique circulant à une vitesse manifestement excessive par rapport à la limite autorisée pour ce type d''engin, qui s''avère avoir été débridé par rapport à ses réglages d''origine. L''utilisateur, surpris d''être contrôlé, affirme être persuadé d''être dans son bon droit, expliquant que la trottinette était vendue ainsi et qu''il n''a lui-même procédé à aucune modification technique de l''engin.\n\nCette conviction sincère mais erronée traduit une méconnaissance du cadre réglementaire applicable à ce type d''engin de déplacement personnel, dont la réglementation reste relativement récente et possiblement moins bien connue que celle applicable aux véhicules plus traditionnels.\n\nCette situation, sans gravité immédiate au moment du contrôle, pose la question de la manière d''expliquer clairement ce cadre réglementaire à un usager convaincu de bonne foi d''être dans la légalité, plutôt que de se contenter d''une simple sanction sans pédagogie.", "questions": [{"position": 1, "max_points": 5, "label": "Comment traitez-vous cette conviction sincère mais erronée de l''utilisateur sur la légalité de son engin ?", "hint": "La bonne foi apparente de l''usager ne dispense pas de constater l''infraction, mais doit orienter la manière de la lui expliquer.", "perfect": "Je reconnais sa conviction sincère, sans pour autant que cette bonne foi apparente n''efface la réalité objective de l''infraction constituée par cette vitesse excessive et ce débridage constaté.\n\nJe lui explique clairement le cadre réglementaire applicable à ce type d''engin de déplacement personnel, cette explication pédagogique étant d''autant plus nécessaire que la réglementation est relativement récente et possiblement mal connue.\n\nJe reste attentive à la question de l''origine de ce débridage, qu''il en soit ou non responsable directement, cette information pouvant avoir une incidence sur la suite du traitement de cette situation, notamment vis-à-vis du vendeur éventuellement responsable.\n\nJe ne minimise pas pour autant la gravité de cette vitesse excessive, qui constitue un danger réel indépendamment de l''origine du débridage et de la bonne foi de l''utilisateur sur ce point.", "points": [{"position": 1, "label": "Reconnaître la conviction sincère sans effacer la réalité de l''infraction", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : bonne foi n''effaçant pas l''infraction constituée.", "groups": [{"position": 1, "keywords": ["conviction sincère reconnue", "infraction constituée", "pas d''effacement"]}]}, {"position": 2, "label": "Expliquer clairement le cadre réglementaire applicable", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Réglementation récente possiblement mal connue.", "groups": [{"position": 1, "keywords": ["cadre réglementaire expliqué", "réglementation récente", "explication pédagogique"]}]}, {"position": 3, "label": "Rester attentive à l''origine du débridage pour la suite du traitement", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Incidence possible vis-à-vis du vendeur responsable.", "groups": [{"position": 1, "keywords": ["origine du débridage", "vendeur éventuellement responsable", "incidence sur le traitement"]}]}, {"position": 4, "label": "Ne pas minimiser la gravité de la vitesse excessive", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Danger réel indépendamment de l''origine et de la bonne foi.", "groups": [{"position": 1, "keywords": ["danger réel maintenu", "indépendant de la bonne foi", "gravité non minimisée"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment procédez-vous concrètement face à cet engin débridé et à cette vitesse excessive ?", "hint": "L''action concrète doit viser à faire cesser le danger immédiat tout en traitant l''infraction de manière proportionnée.", "perfect": "Je constate l''infraction relative à cette vitesse excessive et à ce débridage, cette qualification devant s''appuyer sur les éléments objectifs constatés lors de ce contrôle.\n\nJe m''assure que cet engin ne puisse pas repartir dans les mêmes conditions de débridage, cette mesure étant nécessaire pour faire cesser le danger que représente cette vitesse excessive sur la voie publique.\n\nJe reste proportionnée dans le traitement de cette situation, cette infraction, bien que réelle, ne relevant pas de la même gravité que d''autres situations plus dangereuses rencontrées dans d''autres contextes routiers.\n\nJe consigne avec précision les circonstances de ce débridage constaté, ces éléments pouvant être utiles si l''utilisateur souhaite se retourner contre le vendeur de cet engin.", "points": [{"position": 1, "label": "Constater l''infraction relative à la vitesse et au débridage", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : qualification s''appuyant sur les éléments objectifs.", "groups": [{"position": 1, "keywords": ["infraction constatée", "éléments objectifs", "vitesse et débridage"]}]}, {"position": 2, "label": "S''assurer que l''engin ne reparte pas dans les mêmes conditions", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Faire cesser le danger sur la voie publique.", "groups": [{"position": 1, "keywords": ["ne pas repartir ainsi", "cesser le danger", "voie publique"]}]}, {"position": 3, "label": "Rester proportionnée dans le traitement de cette situation", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Gravité moindre que d''autres situations routières.", "groups": [{"position": 1, "keywords": ["proportionnalité", "gravité moindre", "autres contextes plus graves"]}]}, {"position": 4, "label": "Consigner précisément les circonstances du débridage constaté", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Utile pour un éventuel recours contre le vendeur.", "groups": [{"position": 1, "keywords": ["débridage consigné", "recours contre le vendeur", "circonstances précises"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment concluez-vous cette intervention en tenant compte du caractère relativement récent de cette réglementation ?", "hint": "La nouveauté relative de ce cadre réglementaire justifie un effort pédagogique particulier plutôt qu''une approche uniquement répressive.", "perfect": "Je conclus cette intervention en m''assurant que l''utilisateur reparte avec une compréhension claire des règles applicables à ce type d''engin, cette pédagogie étant particulièrement importante compte tenu de la nouveauté relative de cette réglementation.\n\nJe reste factuelle sur les conséquences de l''infraction constatée, sans pour autant adopter un ton culpabilisant envers quelqu''un qui semble sincèrement ignorer les règles applicables à son engin.\n\nJe lui recommande de vérifier les caractéristiques exactes de son engin auprès de sources fiables, cette information pouvant l''aider à éviter une récidive involontaire de cette même infraction.\n\nJe garde à l''esprit que cette pédagogie individuelle, bien qu''utile, ne remplace pas une information plus large qui devrait être diffusée sur ce type de réglementation encore mal connue du grand public.", "points": [{"position": 1, "label": "S''assurer d''une compréhension claire des règles applicables", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : pédagogie importante compte tenu de la nouveauté.", "groups": [{"position": 1, "keywords": ["compréhension claire", "pédagogie importante", "réglementation nouvelle"]}]}, {"position": 2, "label": "Rester factuelle sans ton culpabilisant", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Ignorance sincère des règles applicables.", "groups": [{"position": 1, "keywords": ["factuelle sans culpabilisation", "ignorance sincère", "pas de ton accusateur"]}]}, {"position": 3, "label": "Recommander de vérifier les caractéristiques de l''engin", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Éviter une récidive involontaire.", "groups": [{"position": 1, "keywords": ["vérification recommandée", "sources fiables", "récidive évitée"]}]}, {"position": 4, "label": "Considérer que cette pédagogie individuelle ne remplace pas une information plus large", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Réglementation encore mal connue du grand public.", "groups": [{"position": 1, "keywords": ["pédagogie individuelle limitée", "information plus large", "mal connue du public"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('routier-conducteur-fuite-apres-controle-alcool', '{"slug": "routier-conducteur-fuite-apres-controle-alcool", "title": "Il remonte en voiture pendant que vous préparez l''éthylotest", "theme_slug": "circulation", "difficulty": "difficile", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 30, "situation_text": "Il est 2 heures du matin. Vous contrôlez un conducteur suspecté d''alcoolémie et lui demandez de patienter pendant que vous préparez le matériel de dépistage. Profitant de ce court instant où votre attention est momentanément portée sur ce matériel, il remonte brusquement dans son véhicule et démarre en trombe, s''échappant du contrôle en cours avant même que l''éthylotest n''ait pu être réalisé.\n\nCette fuite, intervenant pendant l''acte même du contrôle plutôt qu''après un accident déjà survenu, présente une configuration particulière où le danger de sa conduite potentiellement alcoolisée se combine désormais avec celui d''une fuite précipitée dans les rues à cette heure tardive.\n\nCette situation impose une décision rapide sur l''opportunité d''engager une poursuite immédiate de ce véhicule, dans un contexte où l''état d''alcoolémie suspecté du conducteur pourrait rendre sa conduite d''autant plus imprévisible et dangereuse en cas de course-poursuite.", "questions": [{"position": 1, "max_points": 5, "label": "Comment évaluez-vous l''opportunité d''engager une poursuite immédiate de ce conducteur qui vient de fuir pendant le contrôle ?", "hint": "L''état d''alcoolémie suspecté doit peser lourdement dans l''évaluation du risque qu''une poursuite immédiate ferait courir à tous.", "perfect": "J''évalue que cette poursuite comporterait un risque particulièrement élevé, l''état d''alcoolémie suspecté de ce conducteur pouvant rendre sa conduite de fuite encore plus imprévisible et dangereuse qu''une fuite ordinaire.\n\nJe considère que l''objectif d''interpellation immédiate doit être mis en balance avec ce risque accru, cette combinaison entre alcoolémie suspectée et fuite précipitée créant une situation particulièrement préoccupante pour la sécurité de tous les usagers de la route à cette heure.\n\nJe reste attentive au fait que cette fuite pendant l''acte même du contrôle traduit une prise de risque déjà élevée de la part de ce conducteur, ce qui peut laisser présager une conduite tout aussi risquée durant une éventuelle poursuite.\n\nJe privilégie une approche qui limite l''escalade du risque plutôt qu''une poursuite immédiate à tout prix, cette décision devant rester guidée par l''évaluation objective du danger plutôt que par la seule volonté de rattraper ce conducteur fautif.", "points": [{"position": 1, "label": "Évaluer un risque particulièrement élevé lié à l''alcoolémie suspectée", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : conduite de fuite d''autant plus imprévisible.", "groups": [{"position": 1, "keywords": ["risque particulièrement élevé", "alcoolémie suspectée", "conduite imprévisible"]}]}, {"position": 2, "label": "Mettre en balance l''objectif d''interpellation avec ce risque accru", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Situation préoccupante pour tous les usagers.", "groups": [{"position": 1, "keywords": ["mise en balance", "situation préoccupante", "sécurité de tous"]}]}, {"position": 3, "label": "Considérer que la fuite traduit déjà une prise de risque élevée", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Présageant une conduite tout aussi risquée en poursuite.", "groups": [{"position": 1, "keywords": ["prise de risque élevée", "présager la poursuite", "conduite risquée"]}]}, {"position": 4, "label": "Privilégier limiter l''escalade plutôt qu''une poursuite à tout prix", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Décision guidée par l''évaluation objective du danger.", "groups": [{"position": 1, "keywords": ["limiter l''escalade", "pas à tout prix", "évaluation objective"]}]}]}, {"position": 2, "max_points": 5, "label": "Quelle alternative concrète privilégiez-vous à une poursuite immédiate à haut risque ?", "hint": "Le signalement rapide de ce véhicule en fuite constitue une alternative permettant de traiter la situation sans engager une course-poursuite risquée.", "perfect": "Je privilégie un signalement immédiat de ce véhicule en fuite, avec les éléments d''identification dont je dispose, cette transmission rapide permettant une interpellation ultérieure par d''autres moyens que la poursuite directe.\n\nJe communique sans délai cette fuite aux collègues et aux moyens disponibles dans le secteur, cette diffusion large augmentant les chances d''interception de ce véhicule dans des conditions plus sécurisées.\n\nJe reste attentive à la direction prise par ce véhicule au moment de sa fuite, cette information pouvant orienter utilement les recherches ultérieures sans nécessiter ma propre poursuite immédiate.\n\nJe consigne avec précision l''ensemble des éléments de ce contrôle avant fuite, notamment les signes d''alcoolémie déjà constatés, ces éléments constituant une base solide pour la suite du traitement de cette affaire.", "points": [{"position": 1, "label": "Privilégier un signalement immédiat avec les éléments d''identification", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : interpellation ultérieure par d''autres moyens.", "groups": [{"position": 1, "keywords": ["signalement immédiat", "éléments d''identification", "interpellation ultérieure"]}]}, {"position": 2, "label": "Communiquer sans délai aux collègues et moyens disponibles", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Diffusion large augmentant les chances d''interception.", "groups": [{"position": 1, "keywords": ["communication sans délai", "diffusion large", "conditions sécurisées"]}]}, {"position": 3, "label": "Rester attentive à la direction prise pour orienter les recherches", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Sans nécessiter la propre poursuite immédiate.", "groups": [{"position": 1, "keywords": ["direction observée", "orienter les recherches", "sans poursuite propre"]}]}, {"position": 4, "label": "Consigner précisément les signes d''alcoolémie déjà constatés", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Base solide pour la suite du traitement.", "groups": [{"position": 1, "keywords": ["signes consignés", "base solide", "avant la fuite"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment traitez-vous cette affaire une fois ce conducteur éventuellement retrouvé par d''autres moyens ?", "hint": "L''absence d''éthylotest réalisé au moment du contrôle initial ne clôt pas la possibilité de qualifier les faits sur la base des éléments déjà recueillis et de la fuite elle-même.", "perfect": "Je transmets l''ensemble des éléments recueillis lors de ce contrôle interrompu par la fuite, ces informations constituant une base importante même en l''absence du résultat de l''éthylotest qui n''a pas pu être réalisé.\n\nJe consigne avec précision le fait que ce conducteur a fui spécifiquement au moment où l''éthylotest allait être présenté, cette circonstance pouvant elle-même être significative dans l''appréciation de la situation d''ensemble.\n\nJe reste attentive à ce que la qualification exacte de cette fuite pendant l''acte de contrôle soit correctement établie, cette configuration se distinguant d''une fuite après un accident déjà survenu.\n\nJe transmets ces éléments aux services compétents pour la suite du traitement, en sachant que l''identification et l''interpellation ultérieure de ce conducteur permettront d''établir plus précisément les responsabilités de cette double infraction.", "points": [{"position": 1, "label": "Transmettre l''ensemble des éléments malgré l''absence d''éthylotest réalisé", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : base importante malgré l''interruption du contrôle.", "groups": [{"position": 1, "keywords": ["éléments transmis", "malgré l''absence d''éthylotest", "base importante"]}]}, {"position": 2, "label": "Consigner que la fuite est intervenue au moment précis de l''éthylotest", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Circonstance significative dans l''appréciation.", "groups": [{"position": 1, "keywords": ["fuite au moment précis", "circonstance significative", "appréciation d''ensemble"]}]}, {"position": 3, "label": "S''assurer que la qualification de cette fuite pendant le contrôle soit établie", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Distinct d''une fuite après accident.", "groups": [{"position": 1, "keywords": ["qualification établie", "distinct de la fuite après accident", "configuration particulière"]}]}, {"position": 4, "label": "Transmettre pour établir les responsabilités de cette double infraction", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Interpellation ultérieure précisant les responsabilités.", "groups": [{"position": 1, "keywords": ["double infraction", "responsabilités précisées", "interpellation ultérieure"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('routier-manifestation-blocage-circulation', '{"slug": "routier-manifestation-blocage-circulation", "title": "Des tracteurs bloquent l''accès à la zone commerciale", "theme_slug": "circulation", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 7 heures. Une trentaine d''agriculteurs, mécontents de mesures qu''ils jugent défavorables à leur activité, bloquent avec leurs tracteurs l''accès principal à une zone commerciale, dans le cadre d''une action revendicative annoncée la veille par leurs organisations professionnelles. Cette action, bien qu''ayant un impact certain sur la circulation, se déroule dans un climat globalement calme, sans provocation directe envers vous ni envers les usagers bloqués.\n\nPlusieurs automobilistes, bloqués depuis le début de cette action, commencent à manifester leur propre impatience, certains klaxonnant ou descendant de leur véhicule pour interpeller directement les agriculteurs sur la durée de ce blocage qui les empêche de rejoindre leur travail à l''heure prévue.\n\nCette situation croise un enjeu d''ordre public lié à cette action revendicative collective et la nécessité de préserver, autant que possible, les accès essentiels, notamment pour d''éventuels véhicules de secours qui pourraient avoir besoin d''emprunter cette voie.", "questions": [{"position": 1, "max_points": 5, "label": "Comment abordez-vous cette action revendicative collective, dans un climat qui reste pour l''instant calme ?", "hint": "Le caractère organisé et annoncé de cette action, ainsi que l''absence de provocation directe, doivent orienter vers une posture de dialogue plutôt que de confrontation immédiate.", "perfect": "J''aborde cette action en reconnaissant sa dimension revendicative légitime, cette manifestation ayant été annoncée par les organisations professionnelles et se déroulant, pour l''instant, dans un climat globalement calme et sans provocation directe.\n\nJe privilégie une posture de dialogue avec les représentants de ce mouvement, cette communication pouvant permettre de comprendre leurs intentions précises sur la durée envisagée de ce blocage et les modalités de son déroulement.\n\nJe reste attentive à ne pas adopter une posture de confrontation immédiate qui pourrait inutilement envenimer une situation qui reste, à ce stade, maîtrisée et sans danger particulier pour qui que ce soit.\n\nJe maintiens ma vigilance sur l''évolution de cette situation, ce climat calme pouvant potentiellement se dégrader si la tension monte entre les agriculteurs et les automobilistes bloqués.", "points": [{"position": 1, "label": "Reconnaître la dimension revendicative légitime dans un climat calme", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : action organisée et annoncée sans provocation.", "groups": [{"position": 1, "keywords": ["dimension revendicative", "action annoncée", "climat calme"]}]}, {"position": 2, "label": "Privilégier une posture de dialogue avec les représentants du mouvement", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Comprendre les intentions sur la durée et les modalités.", "groups": [{"position": 1, "keywords": ["dialogue privilégié", "représentants du mouvement", "intentions comprises"]}]}, {"position": 3, "label": "Ne pas adopter une posture de confrontation immédiate", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Éviter d''envenimer une situation maîtrisée.", "groups": [{"position": 1, "keywords": ["pas de confrontation", "situation maîtrisée", "pas d''envenimement"]}]}, {"position": 4, "label": "Maintenir sa vigilance sur l''évolution possible de la situation", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Climat calme pouvant se dégrader avec la tension montante.", "groups": [{"position": 1, "keywords": ["vigilance maintenue", "évolution possible", "tension montante"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment gérez-vous l''impatience croissante des automobilistes bloqués, dont certains interpellent directement les agriculteurs ?", "hint": "Cette impatience légitime des usagers bloqués ne doit pas être ignorée, mais nécessite une gestion qui évite une confrontation directe entre les deux groupes.", "perfect": "Je reconnais la légitimité de l''impatience de ces automobilistes, cette gêne réelle pour leurs déplacements justifiant leur frustration face à un blocage dont ils ne maîtrisent ni la cause ni la durée.\n\nJe m''interpose si nécessaire entre les automobilistes les plus véhéments et les agriculteurs, cette interposition visant à éviter une confrontation directe entre ces deux groupes aux intérêts contradictoires dans l''instant.\n\nJe communique aux automobilistes les informations dont je dispose sur la durée probable de ce blocage, cette transparence pouvant contribuer à apaiser leur frustration en leur donnant une visibilité, même approximative, sur la situation.\n\nJe recherche, si possible, des itinéraires alternatifs à leur suggérer, cette solution pratique pouvant limiter le nombre de personnes directement affectées par ce blocage prolongé.", "points": [{"position": 1, "label": "Reconnaître la légitimité de l''impatience des automobilistes", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : frustration légitime face au blocage.", "groups": [{"position": 1, "keywords": ["impatience légitime reconnue", "gêne réelle", "frustration justifiée"]}]}, {"position": 2, "label": "S''interposer si nécessaire entre automobilistes et agriculteurs", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Éviter une confrontation directe entre les deux groupes.", "groups": [{"position": 1, "keywords": ["interposition", "confrontation évitée", "deux groupes"]}]}, {"position": 3, "label": "Communiquer les informations disponibles sur la durée probable", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Transparence apaisant la frustration.", "groups": [{"position": 1, "keywords": ["informations communiquées", "durée probable", "transparence apaisante"]}]}, {"position": 4, "label": "Rechercher des itinéraires alternatifs à suggérer", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Limiter le nombre de personnes affectées.", "groups": [{"position": 1, "keywords": ["itinéraires alternatifs", "solution pratique", "personnes affectées limitées"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment vous assurez-vous que les accès essentiels, notamment pour d''éventuels secours, restent préservés malgré ce blocage ?", "hint": "La préservation d''un passage pour les véhicules de secours doit être négociée avec les organisateurs comme un enjeu prioritaire indépendant du reste du blocage.", "perfect": "Je négocie avec les représentants du mouvement la préservation d''un passage possible pour d''éventuels véhicules de secours, cet enjeu de sécurité vitale devant être distingué du reste de la problématique de circulation générale.\n\nJe reste attentive à ce que cette négociation se fasse dans un climat de respect mutuel, en expliquant clairement pourquoi cet enjeu spécifique dépasse la seule question de la fluidité de la circulation ordinaire.\n\nJe m''assure que ce passage réservé, si accordé, soit clairement identifié et communiqué aux services de secours qui pourraient en avoir besoin durant la durée de ce blocage.\n\nJe reste vigilante à ce que cet accord, s''il est obtenu, soit respecté dans la durée, une vigilance continue étant nécessaire tant que ce blocage collectif se poursuit.", "points": [{"position": 1, "label": "Négocier la préservation d''un passage pour les véhicules de secours", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : enjeu de sécurité vitale distinct du reste.", "groups": [{"position": 1, "keywords": ["passage négocié", "véhicules de secours", "sécurité vitale distincte"]}]}, {"position": 2, "label": "Mener cette négociation dans un climat de respect mutuel", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Expliquer que l''enjeu dépasse la seule fluidité.", "groups": [{"position": 1, "keywords": ["respect mutuel", "enjeu au-delà de la fluidité", "explication claire"]}]}, {"position": 3, "label": "S''assurer que ce passage soit clairement identifié et communiqué", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Aux services de secours qui pourraient en avoir besoin.", "groups": [{"position": 1, "keywords": ["passage identifié", "communiqué aux secours", "accès réservé"]}]}, {"position": 4, "label": "Rester vigilante au respect de cet accord dans la durée", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Vigilance continue tant que le blocage se poursuit.", "groups": [{"position": 1, "keywords": ["vigilance continue", "accord respecté", "durée du blocage"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('routier-vehicule-force-barrage-inondation', '{"slug": "routier-vehicule-force-barrage-inondation", "title": "Il déplace le panneau pour passer quand même", "theme_slug": "circulation", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 19 heures. Vous constatez qu''un conducteur, arrivé face à un panneau signalant une route submergée par des inondations, descend de son véhicule pour déplacer délibérément ce panneau et poursuivre sa route malgré cette signalisation claire, avant que vous n''ayez le temps d''intervenir pour l''en empêcher. Ce comportement traduit une mise en danger volontaire et consciente, ce conducteur ayant explicitement contourné un dispositif de sécurité mis en place pour cette raison précise.\n\nAu-delà du risque direct qu''il fait courir à lui-même en s''engageant sur cette route submergée, ce comportement crée également un risque secondaire pour les éventuels secours qui pourraient devoir intervenir en urgence si son véhicule venait à se retrouver bloqué ou emporté par les eaux.\n\nCette situation, marquée par un franchissement délibéré et conscient d''un dispositif de sécurité, nécessite une réaction rapide pour empêcher ce passage tout en faisant comprendre au conducteur la gravité réelle du risque qu''il s''apprête à prendre.", "questions": [{"position": 1, "max_points": 5, "label": "Comment intervenez-vous pour empêcher ce conducteur de franchir cette route submergée malgré son intention manifeste ?", "hint": "L''intervention doit être rapide et ferme, ce déplacement du panneau traduisant une intention délibérée qui nécessite une réaction immédiate.", "perfect": "J''interviens sans délai pour l''empêcher de poursuivre son passage, ce déplacement délibéré du panneau traduisant une intention manifeste qui nécessite une réaction rapide de ma part.\n\nJe reste ferme dans cette intervention, cette fermeté étant justifiée par le caractère conscient et délibéré de sa décision de contourner un dispositif de sécurité mis en place précisément pour éviter ce type de mise en danger.\n\nJe replace le panneau qu''il vient de déplacer, cette action étant nécessaire pour rétablir l''intégrité du dispositif de sécurité initial, indépendamment de la suite donnée à son comportement.\n\nJe reste attentive à ma propre sécurité durant cette intervention, cette zone inondée pouvant elle-même présenter des dangers si je devais m''en approcher trop près pour l''empêcher physiquement de passer.", "points": [{"position": 1, "label": "Intervenir sans délai pour empêcher la poursuite du passage", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : intention manifeste nécessitant une réaction rapide.", "groups": [{"position": 1, "keywords": ["intervention sans délai", "intention manifeste", "réaction rapide"]}]}, {"position": 2, "label": "Rester ferme compte tenu du caractère conscient et délibéré", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Contournement délibéré d''un dispositif de sécurité.", "groups": [{"position": 1, "keywords": ["fermeté justifiée", "caractère délibéré", "dispositif de sécurité"]}]}, {"position": 3, "label": "Replacer le panneau déplacé pour rétablir le dispositif", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Indépendamment de la suite donnée à son comportement.", "groups": [{"position": 1, "keywords": ["panneau replacé", "dispositif rétabli", "intégrité initiale"]}]}, {"position": 4, "label": "Rester attentive à sa propre sécurité durant l''intervention", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Zone inondée présentant elle-même des dangers.", "groups": [{"position": 1, "keywords": ["propre sécurité", "zone inondée dangereuse", "approche prudente"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment expliquez-vous à ce conducteur la gravité réelle du risque qu''il s''apprêtait à prendre ?", "hint": "L''explication doit dépasser le simple rappel de l''interdiction pour transmettre une compréhension réelle des dangers spécifiques d''une route submergée.", "perfect": "Je lui explique concrètement les dangers spécifiques d''un franchissement de route submergée, notamment le risque que son véhicule soit emporté par le courant ou immobilisé de manière à le mettre lui-même en danger de noyade.\n\nJe reste ferme sur le fait que cette signalisation n''était pas une simple précaution excessive, mais correspondait à un danger réel et documenté que les services compétents avaient identifié pour cette portion de route à ce moment précis.\n\nJe l''informe également du risque secondaire qu''il aurait fait courir aux équipes de secours, ces dernières devant potentiellement s''exposer elles-mêmes à un danger pour venir le récupérer s''il s''était retrouvé bloqué.\n\nJe reste attentive à sa réaction face à ces explications, cette prise de conscience étant importante pour qu''il comprenne la gravité de son geste au-delà de la seule dimension d''infraction administrative.", "points": [{"position": 1, "label": "Expliquer concrètement les dangers spécifiques d''une route submergée", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : risque de véhicule emporté ou noyade.", "groups": [{"position": 1, "keywords": ["dangers concrets expliqués", "véhicule emporté", "risque de noyade"]}]}, {"position": 2, "label": "Rester ferme sur le caractère réel et documenté du danger signalé", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Pas une simple précaution excessive.", "groups": [{"position": 1, "keywords": ["danger réel et documenté", "pas de précaution excessive", "services compétents"]}]}, {"position": 3, "label": "L''informer du risque secondaire pour les équipes de secours", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Exposition potentielle des secours à un danger.", "groups": [{"position": 1, "keywords": ["risque pour les secours", "exposition potentielle", "récupération dangereuse"]}]}, {"position": 4, "label": "Rester attentive à sa réaction face à ces explications", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Prise de conscience au-delà de l''infraction administrative.", "groups": [{"position": 1, "keywords": ["réaction observée", "prise de conscience", "au-delà de l''administratif"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment traitez-vous cette infraction caractérisée par ce contournement délibéré d''un dispositif de sécurité ?", "hint": "Le caractère délibéré de ce franchissement mérite un traitement à la hauteur de la gravité de cette mise en danger consciente.", "perfect": "Je qualifie cette infraction avec toute la gravité que mérite ce contournement délibéré et conscient d''un dispositif de sécurité, ce comportement se distinguant nettement d''une simple négligence ou méconnaissance.\n\nJe consigne avec précision les circonstances de ce déplacement du panneau, cet élément matériel objectivant le caractère délibéré de sa démarche plutôt qu''une simple erreur d''appréciation de sa part.\n\nJe reste attentive à la nécessité de dissuader ce type de comportement pour l''avenir, cette mise en danger consciente d''un dispositif de sécurité méritant une réponse qui décourage sa répétition future.\n\nJe m''assure que cette route reste correctement signalée après mon intervention, cette vigilance étant nécessaire pour éviter que d''autres conducteurs ne soient tentés de reproduire ce même comportement dangereux.", "points": [{"position": 1, "label": "Qualifier avec toute la gravité ce contournement délibéré", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : distinct d''une simple négligence.", "groups": [{"position": 1, "keywords": ["gravité qualifiée", "contournement délibéré", "distinct de la négligence"]}]}, {"position": 2, "label": "Consigner précisément les circonstances du déplacement du panneau", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Élément objectivant le caractère délibéré.", "groups": [{"position": 1, "keywords": ["circonstances consignées", "panneau déplacé", "caractère délibéré objectivé"]}]}, {"position": 3, "label": "Chercher à dissuader ce type de comportement pour l''avenir", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Réponse décourageant la répétition future.", "groups": [{"position": 1, "keywords": ["dissuasion", "réponse décourageante", "répétition future"]}]}, {"position": 4, "label": "S''assurer que la route reste correctement signalée après l''intervention", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Éviter que d''autres reproduisent ce comportement.", "groups": [{"position": 1, "keywords": ["signalisation maintenue", "autres conducteurs", "comportement non reproduit"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('routier-accident-sans-tiers-conducteur-fuit-a-pied', '{"slug": "routier-accident-sans-tiers-conducteur-fuit-a-pied", "title": "Le véhicule est encastré, personne à bord, le moteur est chaud", "theme_slug": "circulation", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 4 heures du matin. Vous découvrez un véhicule encastré dans un fossé en bordure de route, moteur encore chaud signe d''un accident récent, mais sans aucune personne présente à bord ni aux abords immédiats du véhicule. Cette configuration suggère que le conducteur, seul occupant apparent selon les éléments disponibles, aurait fui à pied après cet accident, potentiellement blessé compte tenu de la violence apparente du choc au vu des dommages sur le véhicule.\n\nCette situation nocturne, dans une zone probablement peu fréquentée à cette heure, pose la question prioritaire de la recherche de ce conducteur potentiellement blessé et errant seul dans l''obscurité, plutôt que du seul traitement de l''infraction que pourrait constituer cette fuite après accident.\n\nAucun élément ne permet à ce stade de savoir dans quelle direction ce conducteur aurait pu partir, ni l''étendue exacte de ses éventuelles blessures, cette incertitude rendant d''autant plus urgente une recherche méthodique dans les environs immédiats de l''accident.", "questions": [{"position": 1, "max_points": 5, "label": "Quelle est votre priorité face à cette découverte d''un véhicule accidenté sans occupant apparent ?", "hint": "La recherche du conducteur potentiellement blessé doit primer sur le traitement de l''infraction que pourrait constituer sa fuite.", "perfect": "Ma priorité est la recherche de ce conducteur potentiellement blessé, cette personne pouvant errer dans l''obscurité à proximité de l''accident dans un état nécessitant une prise en charge médicale urgente.\n\nJe ne me concentre pas d''abord sur la qualification de fuite après accident, cette dimension procédurale devant attendre que la question de sa sécurité physique immédiate soit traitée en priorité.\n\nJe recherche des indices sur la direction qu''il aurait pu prendre, comme des traces au sol, des vêtements ou tout autre élément pouvant orienter mes recherches dans cette zone qui reste peu fréquentée à cette heure.\n\nJe sollicite des moyens complémentaires pour élargir le périmètre de recherche, cette urgence nécessitant une mobilisation rapide compte tenu du risque que cette personne, si elle est blessée, ne puisse pas se manifester elle-même.", "points": [{"position": 1, "label": "Prioriser la recherche du conducteur potentiellement blessé", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : sécurité physique avant la dimension procédurale.", "groups": [{"position": 1, "keywords": ["recherche prioritaire", "conducteur blessé", "sécurité physique"]}]}, {"position": 2, "label": "Ne pas se concentrer d''abord sur la qualification de fuite", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Dimension procédurale attendant la sécurité immédiate.", "groups": [{"position": 1, "keywords": ["pas la qualification d''abord", "procédural en attente", "sécurité immédiate"]}]}, {"position": 3, "label": "Rechercher des indices sur la direction prise", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Traces au sol ou éléments orientant les recherches.", "groups": [{"position": 1, "keywords": ["indices de direction", "traces au sol", "orienter les recherches"]}]}, {"position": 4, "label": "Solliciter des moyens complémentaires pour élargir le périmètre", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Mobilisation rapide compte tenu du risque.", "groups": [{"position": 1, "keywords": ["moyens complémentaires", "périmètre élargi", "mobilisation rapide"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment évaluez-vous la gravité probable de l''état de ce conducteur, compte tenu des éléments disponibles sur l''accident ?", "hint": "La violence apparente du choc, déduite de l''état du véhicule, doit orienter l''urgence accordée à cette recherche.", "perfect": "J''évalue la gravité probable de son état à partir des dommages visibles sur le véhicule, cette violence apparente du choc suggérant des blessures potentiellement sérieuses malgré l''absence de sang ou d''autres indices directs sur place.\n\nJe reste attentive au fait que le moteur encore chaud indique un accident très récent, ce qui signifie que ce conducteur, s''il est blessé, n''a pu s''éloigner que sur une distance limitée depuis les faits.\n\nJe considère que l''absence de personne aux abords immédiats peut aussi traduire une désorientation ou un état de choc qui l''aurait conduit à s''éloigner de manière peu rationnelle plutôt qu''à rester sur place ou à chercher de l''aide directement.\n\nJe ne minimise pas cette situation au seul motif qu''aucun élément visible ne confirme des blessures graves, cette absence d''indice ne devant pas être interprétée comme une absence de risque réel pour cette personne.", "points": [{"position": 1, "label": "Évaluer la gravité probable à partir des dommages visibles", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : violence du choc suggérant des blessures potentielles.", "groups": [{"position": 1, "keywords": ["gravité évaluée", "dommages visibles", "blessures potentielles"]}]}, {"position": 2, "label": "Considérer que le moteur chaud indique un accident très récent", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Distance limitée parcourue depuis les faits.", "groups": [{"position": 1, "keywords": ["moteur chaud", "accident récent", "distance limitée"]}]}, {"position": 3, "label": "Considérer une possible désorientation ou état de choc", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Éloignement peu rationnel plutôt que recherche d''aide directe.", "groups": [{"position": 1, "keywords": ["désorientation possible", "état de choc", "éloignement peu rationnel"]}]}, {"position": 4, "label": "Ne pas minimiser en l''absence d''indice visible de blessure grave", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Absence d''indice ne signifiant pas absence de risque.", "groups": [{"position": 1, "keywords": ["pas de minimisation", "absence d''indice", "risque réel maintenu"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment articulez-vous la recherche de ce conducteur avec le traitement ultérieur de l''infraction de fuite qu''il pourrait avoir commise ?", "hint": "Une fois la personne retrouvée et prise en charge, le volet procédural doit être traité avec la même rigueur que dans toute autre situation similaire.", "perfect": "Je consigne avec précision l''ensemble des constatations effectuées sur le véhicule et les lieux de l''accident, ces éléments constituant une base essentielle pour la suite du traitement de cette affaire, quelle que soit l''issue de la recherche.\n\nJe reste attentive à ce que la priorité donnée à sa recherche ne conduise pas à négliger la préservation des éléments de preuve sur place, ces deux objectifs pouvant être poursuivis simultanément par une organisation appropriée des moyens disponibles.\n\nJe traiterai la question de la fuite après accident une fois cette personne retrouvée et sa situation médicale stabilisée, cette qualification restant pertinente indépendamment de l''urgence sanitaire qui prévaut dans l''immédiat.\n\nJe reste consciente que cette recherche pourrait révéler des circonstances particulières, comme un état de choc ou une confusion post-traumatique, qui pourraient nuancer l''appréciation de cette fuite sans pour autant l''exonérer complètement.", "points": [{"position": 1, "label": "Consigner précisément les constatations sur le véhicule et les lieux", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : base essentielle quelle que soit l''issue.", "groups": [{"position": 1, "keywords": ["constatations consignées", "base essentielle", "quelle que soit l''issue"]}]}, {"position": 2, "label": "Ne pas négliger la préservation des éléments de preuve", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Deux objectifs poursuivis simultanément.", "groups": [{"position": 1, "keywords": ["preuves préservées", "objectifs simultanés", "organisation appropriée"]}]}, {"position": 3, "label": "Traiter la fuite une fois la personne retrouvée et stabilisée", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Qualification pertinente indépendamment de l''urgence sanitaire.", "groups": [{"position": 1, "keywords": ["fuite traitée après", "personne stabilisée", "qualification pertinente"]}]}, {"position": 4, "label": "Rester consciente que l''état de choc pourrait nuancer sans exonérer", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Confusion post-traumatique à prendre en compte.", "groups": [{"position": 1, "keywords": ["nuance possible", "confusion post-traumatique", "pas d''exonération complète"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('routier-differend-place-handicape', '{"slug": "routier-differend-place-handicape", "title": "La carte appartient à sa mère, restée à la maison", "theme_slug": "circulation", "difficulty": "facile", "is_free": true, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 20, "situation_text": "Il est 15 heures. Un riverain indigné vous alerte sur un véhicule stationné sur une place réservée aux personnes handicapées, arborant une carte de stationnement qui, après vérification, appartient en réalité à la mère du conducteur, restée à son domicile et n''accompagnant donc pas ce trajet. Le conducteur reconnaît facilement ce détournement, expliquant qu''il ne comptait rester que quelques minutes pour une course rapide et que sa mère, elle, n''a pas eu besoin de cette place aujourd''hui.\n\nLe riverain qui a signalé cette situation reste présent et manifeste une indignation croissante, estimant que ce type de comportement prive potentiellement une personne réellement en situation de handicap d''un accès dont elle aurait besoin dans l''immédiat.\n\nCette situation, banale dans son objet mais révélatrice d''un usage détourné d''un droit destiné à des personnes vulnérables, nécessite un traitement qui ne cède pas à la pression du témoin indigné tout en traitant les faits avec la rigueur appropriée.", "questions": [{"position": 1, "max_points": 5, "label": "Comment qualifiez-vous ce détournement d''usage de la carte de stationnement, malgré les explications données par le conducteur ?", "hint": "Le caractère bref du stationnement invoqué par le conducteur ne change rien à la réalité du détournement d''un droit réservé à d''autres.", "perfect": "Je qualifie cette situation comme un usage détourné caractérisé, la brièveté invoquée du stationnement ne changeant rien à la réalité de cette utilisation d''un droit qui n''appartient pas à ce conducteur pour ce trajet précis.\n\nJe reste attentive au fait que cette carte est associée à la personne handicapée elle-même et non au véhicule ou à la famille en général, ce principe étant central pour comprendre pourquoi cette utilisation constitue une infraction malgré l''absence de la mère lors de ce trajet.\n\nJe ne me laisse pas convaincre par l''argument selon lequel sa mère n''aurait pas eu besoin de cette place aujourd''hui, cette place restant réservée aux personnes en situation de handicap présentes, indépendamment de l''usage que la titulaire de la carte en aurait fait ce jour-là.\n\nJe constate cette infraction avec la rigueur appropriée, ce détournement d''un dispositif destiné à des personnes vulnérables méritant un traitement sérieux malgré son apparence de situation mineure.", "points": [{"position": 1, "label": "Qualifier comme usage détourné caractérisé malgré la brièveté invoquée", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : détournement réel indépendamment de la durée.", "groups": [{"position": 1, "keywords": ["usage détourné caractérisé", "brièveté sans effet", "réalité du détournement"]}]}, {"position": 2, "label": "Rappeler que la carte est associée à la personne, pas au véhicule", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Principe central de l''infraction constituée.", "groups": [{"position": 1, "keywords": ["carte associée à la personne", "pas au véhicule", "principe central"]}]}, {"position": 3, "label": "Ne pas se laisser convaincre par l''absence de besoin de la mère ce jour-là", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Place réservée aux personnes présentes, indépendamment de l''usage de la titulaire.", "groups": [{"position": 1, "keywords": ["pas convaincue", "place réservée aux présents", "indépendant de l''usage habituel"]}]}, {"position": 4, "label": "Constater l''infraction avec la rigueur appropriée malgré son apparence mineure", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Détournement d''un dispositif pour personnes vulnérables.", "groups": [{"position": 1, "keywords": ["rigueur appropriée", "dispositif pour vulnérables", "traitement sérieux"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment gérez-vous la présence du riverain indigné, dont l''indignation croissante pourrait influencer votre traitement de cette situation ?", "hint": "L''indignation légitime du témoin ne doit ni être ignorée ni dicter un traitement disproportionné par rapport à la gravité réelle des faits.", "perfect": "Je reconnais la légitimité de l''indignation de ce riverain, sa préoccupation pour les personnes réellement en situation de handicap traduisant une vigilance citoyenne que je ne minimise pas.\n\nJe reste néanmoins attentive à ne pas laisser cette indignation, aussi légitime soit-elle, dicter un traitement disproportionné par rapport à la gravité réelle de ces faits, qui reste une infraction de stationnement plutôt qu''un acte d''une gravité exceptionnelle.\n\nJe traite cette situation avec la même rigueur méthodique que j''appliquerais en l''absence de ce témoin, en évitant de céder à une pression extérieure qui pourrait m''inciter à une sévérité disproportionnée pour satisfaire son indignation.\n\nJe remercie ce riverain pour son signalement, cette vigilance citoyenne restant utile pour détecter ce type de détournement, tout en gérant la suite de cette intervention selon mon appréciation professionnelle propre.", "points": [{"position": 1, "label": "Reconnaître la légitimité de l''indignation sans la minimiser", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : vigilance citoyenne reconnue.", "groups": [{"position": 1, "keywords": ["indignation légitime", "vigilance citoyenne", "pas minimisée"]}]}, {"position": 2, "label": "Ne pas laisser l''indignation dicter un traitement disproportionné", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Infraction de stationnement, pas une gravité exceptionnelle.", "groups": [{"position": 1, "keywords": ["pas de disproportion", "infraction de stationnement", "gravité réelle"]}]}, {"position": 3, "label": "Traiter avec la même rigueur méthodique qu''en l''absence de témoin", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Éviter une sévérité disproportionnée par pression extérieure.", "groups": [{"position": 1, "keywords": ["rigueur méthodique", "pas de pression extérieure", "appréciation propre"]}]}, {"position": 4, "label": "Remercier le riverain pour son signalement utile", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Vigilance citoyenne utile pour détecter ce type de détournement.", "groups": [{"position": 1, "keywords": ["remerciement", "signalement utile", "vigilance citoyenne"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment concluez-vous cette intervention en tenant compte du caractère de première reconnaissance des faits par le conducteur ?", "hint": "La reconnaissance facile des faits par le conducteur peut être prise en compte dans la manière de conclure sans pour autant annuler l''infraction constatée.", "perfect": "Je constate l''infraction relative à cet usage détourné de la carte de stationnement, cette qualification restant nécessaire malgré la reconnaissance facile des faits par le conducteur.\n\nJe reste attentive au fait que cette reconnaissance spontanée traduit une certaine bonne foi sur le plan de la transparence, sans que cela ne remette en cause la réalité de l''infraction elle-même qui reste caractérisée.\n\nJe profite de cette occasion pour lui expliquer clairement pourquoi ce type de comportement, même bref et apparemment sans conséquence immédiate, prive potentiellement une personne handicapée d''un accès dont elle pourrait avoir besoin à tout moment.\n\nJe consigne cette intervention de manière proportionnée à sa nature réelle, ni en la banalisant excessivement ni en la traitant avec une sévérité qui ne correspondrait pas à la gravité objective de ce fait de stationnement.", "points": [{"position": 1, "label": "Constater l''infraction malgré la reconnaissance facile des faits", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : qualification nécessaire malgré la reconnaissance.", "groups": [{"position": 1, "keywords": ["infraction constatée", "reconnaissance facile", "qualification maintenue"]}]}, {"position": 2, "label": "Reconnaître la bonne foi de transparence sans annuler l''infraction", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Reconnaissance spontanée n''effaçant pas la réalité des faits.", "groups": [{"position": 1, "keywords": ["bonne foi de transparence", "pas d''annulation", "infraction caractérisée"]}]}, {"position": 3, "label": "Expliquer clairement les conséquences pour une personne handicapée", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Privation potentielle d''un accès nécessaire.", "groups": [{"position": 1, "keywords": ["conséquences expliquées", "privation potentielle", "accès nécessaire"]}]}, {"position": 4, "label": "Consigner de manière proportionnée à la nature réelle des faits", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Ni banalisation ni sévérité disproportionnée.", "groups": [{"position": 1, "keywords": ["consigné proportionnellement", "pas de banalisation", "pas de sévérité disproportionnée"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('routier-defaut-controle-technique-vehicule-dangereux', '{"slug": "routier-defaut-controle-technique-vehicule-dangereux", "title": "Les plaquettes crissent et un pneu est lisse sur toute la largeur", "theme_slug": "circulation", "difficulty": "moyen", "is_free": true, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 16 heures. Lors d''un contrôle routier, vous constatez que le contrôle technique de ce véhicule est expiré depuis plusieurs mois, et une inspection rapide révèle des éléments particulièrement préoccupants : les plaquettes de frein crissent fortement à chaque freinage, et l''un des pneus est complètement lisse sur toute sa largeur, sans aucun relief de sculpture visible. Le conducteur, une mère de famille, explique devoir impérativement récupérer ses enfants à l''école dans les minutes qui suivent, sans solution alternative immédiate.\n\nCes défaillances techniques constituent un danger direct et sérieux, indépendamment de tout contrôle technique expiré sur le plan purement administratif, ce véhicule présentant des risques concrets de perte de contrôle ou d''allongement dangereux des distances de freinage en cas de besoin.\n\nCette situation oppose la nécessité impérative d''immobiliser ce véhicule manifestement dangereux à la contrainte personnelle bien réelle que cette mère de famille invoque pour justifier la poursuite immédiate de son trajet.", "questions": [{"position": 1, "max_points": 5, "label": "Comment qualifiez-vous le danger que représente ce véhicule, au-delà du seul défaut administratif de contrôle technique ?", "hint": "Les défaillances techniques constatées, freins et pneu, créent un danger concret qui dépasse largement la seule question administrative du contrôle expiré.", "perfect": "Je qualifie ce véhicule comme présentant un danger technique direct et sérieux, ces plaquettes de frein qui crissent et ce pneu complètement lisse constituant des défaillances concrètes qui dépassent largement la seule question administrative du contrôle technique expiré.\n\nJe reste attentive au fait que ces défaillances créent des risques réels de perte de contrôle ou d''allongement des distances de freinage, ces conséquences pouvant se matérialiser à tout moment, y compris durant le trajet immédiat qu''elle souhaite effectuer.\n\nJe ne minimise pas ce danger au seul motif que le contrôle technique expiré pourrait sembler une simple formalité administrative, ces éléments techniques constatés étant, eux, d''une gravité intrinsèque indépendante de cette dimension administrative.\n\nJe considère que ce danger technique concerne non seulement la conductrice elle-même, mais aussi ses propres enfants qu''elle s''apprête à récupérer et à transporter dans ce véhicule dans cet état défaillant.", "points": [{"position": 1, "label": "Qualifier comme danger technique direct dépassant l''administratif", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : défaillances concrètes des freins et du pneu.", "groups": [{"position": 1, "keywords": ["danger technique direct", "défaillances concrètes", "au-delà de l''administratif"]}]}, {"position": 2, "label": "Considérer les risques de perte de contrôle ou d''allongement du freinage", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Conséquences pouvant se matérialiser durant le trajet immédiat.", "groups": [{"position": 1, "keywords": ["perte de contrôle", "allongement du freinage", "matérialisation immédiate"]}]}, {"position": 3, "label": "Ne pas minimiser au motif de la simple formalité administrative", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Gravité intrinsèque indépendante de l''administratif.", "groups": [{"position": 1, "keywords": ["pas de minimisation", "gravité intrinsèque", "indépendant de l''administratif"]}]}, {"position": 4, "label": "Considérer le danger pour les enfants qu''elle va transporter", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Pas seulement pour la conductrice elle-même.", "groups": [{"position": 1, "keywords": ["danger pour les enfants", "transport dans cet état", "pas seulement elle-même"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment traitez-vous la contrainte invoquée par cette mère de famille pour récupérer ses enfants à l''école ?", "hint": "Cette contrainte réelle et légitime doit être prise en compte dans la recherche d''une solution, sans pour autant justifier de laisser repartir un véhicule dangereux.", "perfect": "Je reconnais la réalité de cette contrainte, la nécessité de récupérer ses enfants à l''école constituant une préoccupation légitime et urgente pour cette mère de famille.\n\nJe reste néanmoins ferme sur le fait que cette contrainte, aussi légitime soit-elle, ne peut pas justifier de laisser repartir un véhicule présentant un danger technique aussi caractérisé, ce risque pouvant précisément se matérialiser durant ce trajet destiné à récupérer ses propres enfants.\n\nJe l''aide à identifier une solution alternative rapide pour cette urgence précise, comme contacter un proche disponible ou solliciter l''aide de l''établissement scolaire pour une garde temporaire le temps de trouver une solution.\n\nJe reste attentive à ne pas transformer cette immobilisation en une situation de blocage total sans issue, en cherchant activement avec elle une réponse pratique à cette contrainte réelle qu''elle traverse.", "points": [{"position": 1, "label": "Reconnaître la réalité de cette contrainte légitime", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : préoccupation légitime et urgente reconnue.", "groups": [{"position": 1, "keywords": ["contrainte reconnue", "légitime et urgente", "mère de famille"]}]}, {"position": 2, "label": "Rester ferme sur l''immobilisation malgré cette contrainte", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Risque pouvant se matérialiser durant ce trajet précis.", "groups": [{"position": 1, "keywords": ["fermeté maintenue", "immobilisation nécessaire", "risque durant ce trajet"]}]}, {"position": 3, "label": "Aider à identifier une solution alternative rapide", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Proche disponible ou aide de l''établissement scolaire.", "groups": [{"position": 1, "keywords": ["solution alternative", "proche disponible", "aide de l''établissement"]}]}, {"position": 4, "label": "Ne pas transformer en blocage total sans issue", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Réponse pratique à la contrainte réelle.", "groups": [{"position": 1, "keywords": ["pas de blocage total", "réponse pratique", "issue recherchée"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment procédez-vous concrètement à l''immobilisation de ce véhicule dangereux ?", "hint": "L''immobilisation doit être appliquée avec rigueur tout en restant bienveillante dans la manière de la mettre en œuvre face à cette situation personnelle difficile.", "perfect": "Je procède à l''immobilisation de ce véhicule conformément à la procédure applicable à ce type de défaillance technique caractérisée, cette mesure restant nécessaire malgré la contrainte personnelle qu''elle traverse.\n\nJe reste bienveillante dans la manière de mettre en œuvre cette immobilisation, en expliquant clairement les raisons techniques précises qui la justifient plutôt que de me limiter à une application froide et mécanique de la procédure.\n\nJe lui indique clairement les démarches qu''elle devra entreprendre pour faire réparer ce véhicule avant de pouvoir le récupérer, cette information pratique étant utile pour la suite de sa situation.\n\nJe reste disponible pour l''aider à organiser la solution alternative identifiée pour cette urgence précise, cette assistance concrète pouvant atténuer l''impact de cette immobilisation nécessaire sur sa situation immédiate.", "points": [{"position": 1, "label": "Procéder à l''immobilisation conformément à la procédure applicable", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : mesure nécessaire malgré la contrainte.", "groups": [{"position": 1, "keywords": ["immobilisation procédurale", "défaillance caractérisée", "malgré la contrainte"]}]}, {"position": 2, "label": "Rester bienveillante en expliquant les raisons techniques précises", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Plutôt qu''une application froide et mécanique.", "groups": [{"position": 1, "keywords": ["bienveillance", "raisons techniques expliquées", "pas d''application froide"]}]}, {"position": 3, "label": "Indiquer clairement les démarches de réparation nécessaires", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Information pratique pour la suite de sa situation.", "groups": [{"position": 1, "keywords": ["démarches indiquées", "réparation nécessaire", "information pratique"]}]}, {"position": 4, "label": "Rester disponible pour aider à organiser la solution alternative", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Atténuer l''impact sur sa situation immédiate.", "groups": [{"position": 1, "keywords": ["disponibilité pour aider", "solution alternative organisée", "impact atténué"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('routier-conducteur-en-detresse-psychologique', '{"slug": "routier-conducteur-en-detresse-psychologique", "title": "Il conduit depuis onze heures et vous dit qu''il ne veut plus rentrer", "theme_slug": "circulation", "difficulty": "difficile", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 30, "situation_text": "Il est 22 heures. Lors d''un contrôle routier banal sur une aire d''autoroute, un conducteur d''une cinquantaine d''années vous confie spontanément conduire depuis onze heures sans réel objectif de destination, ajoutant sur un ton résigné qu''il « ne veut plus rentrer » chez lui. Cette confidence inattendue, formulée dans le cadre d''un contrôle qui n''avait initialement aucune vocation particulière, révèle une détresse psychologique manifeste qui dépasse largement le seul cadre routier de cette interpellation.\n\nCet homme reste calme, sans agressivité, mais son discours et son état de fatigue évident après une conduite aussi prolongée sans destination claire constituent des signaux préoccupants sur son état mental actuel. Aucun élément ne permet de savoir s''il représente un danger immédiat pour lui-même, mais cette détresse verbalisée directement ne peut être ignorée.\n\nCette situation transforme un contrôle routier ordinaire en une problématique de détresse psychologique qui doit désormais primer sur l''aspect purement routier de cette interpellation, nécessitant une réorientation complète de votre approche envers cet homme.", "questions": [{"position": 1, "max_points": 5, "label": "Comment réagissez-vous immédiatement face à cette confidence inattendue révélant une détresse psychologique manifeste ?", "hint": "Cette confidence doit immédiatement réorienter le traitement de ce contrôle vers la question de la détresse, plutôt que de rester centré sur l''aspect routier initial.", "perfect": "Je prends immédiatement au sérieux cette confidence, cette détresse verbalisée directement par cet homme ne pouvant être ignorée ou traitée comme un simple détail anecdotique de ce contrôle routier.\n\nJe réoriente immédiatement mon approche de cet échange, la question de son état psychologique devenant désormais prioritaire par rapport à l''aspect purement routier qui motivait initialement ce contrôle.\n\nJe reste attentive à son calme apparent sans agressivité, ce comportement ne devant pas me rassurer faussement sur l''absence de risque, une détresse profonde pouvant tout à fait s''exprimer sans manifestation agressive ou spectaculaire.\n\nJe cherche à approfondir doucement cette confidence, sans le brusquer, pour mieux évaluer l''ampleur réelle de sa détresse et les risques éventuels qu''elle pourrait comporter pour lui-même.", "points": [{"position": 1, "label": "Prendre immédiatement au sérieux cette confidence de détresse", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : ne pas ignorer ou minimiser cette révélation.", "groups": [{"position": 1, "keywords": ["confidence prise au sérieux", "pas ignorée", "pas anecdotique"]}]}, {"position": 2, "label": "Réorienter immédiatement l''approche vers la question psychologique", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Priorité désormais sur l''aspect purement routier.", "groups": [{"position": 1, "keywords": ["réorientation immédiate", "priorité psychologique", "au-delà du routier"]}]}, {"position": 3, "label": "Ne pas se rassurer faussement par son calme apparent", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Détresse profonde pouvant s''exprimer sans agressivité.", "groups": [{"position": 1, "keywords": ["pas rassurée par le calme", "détresse sans agressivité", "vigilance maintenue"]}]}, {"position": 4, "label": "Chercher à approfondir doucement cette confidence sans le brusquer", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Mieux évaluer l''ampleur et les risques éventuels.", "groups": [{"position": 1, "keywords": ["approfondir doucement", "sans brusquer", "évaluer les risques"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment évaluez-vous et gérez-vous le risque immédiat que cette détresse pourrait représenter pour lui-même ?", "hint": "L''absence de manifestation évidente de danger ne dispense pas d''une évaluation attentive de ce risque potentiel pour sa propre sécurité.", "perfect": "J''évalue attentivement ce risque en tenant compte de l''ensemble des éléments disponibles, sa fatigue extrême après onze heures de conduite sans destination et cette phrase sur le fait de « ne plus vouloir rentrer » constituant des signaux qui méritent une attention particulière.\n\nJe ne le laisse pas repartir seul au volant dans cet état de fatigue et de détresse combinées, ce cumul de facteurs créant un danger tant pour lui-même que pour les autres usagers s''il devait reprendre la route immédiatement.\n\nJe sollicite un soutien adapté à cette situation de détresse psychologique, cette problématique dépassant mes seules compétences et nécessitant l''intervention de professionnels formés à ce type d''accompagnement.\n\nJe reste présente et rassurante auprès de lui durant cette attente, cette présence pouvant elle-même avoir un effet apaisant en attendant l''arrivée d''un soutien plus adapté à sa situation.", "points": [{"position": 1, "label": "Évaluer attentivement le risque à partir de l''ensemble des signaux", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : fatigue extrême et phrase de détresse combinées.", "groups": [{"position": 1, "keywords": ["évaluation attentive", "signaux combinés", "fatigue et détresse"]}]}, {"position": 2, "label": "Ne pas le laisser repartir seul au volant dans cet état", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Danger pour lui-même et les autres usagers.", "groups": [{"position": 1, "keywords": ["pas de départ seul", "danger pour lui et autrui", "reprise immédiate évitée"]}]}, {"position": 3, "label": "Solliciter un soutien adapté dépassant ses propres compétences", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Professionnels formés à ce type d''accompagnement.", "groups": [{"position": 1, "keywords": ["soutien adapté sollicité", "hors compétence propre", "professionnels formés"]}]}, {"position": 4, "label": "Rester présente et rassurante durant l''attente", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Effet apaisant en attendant un soutien plus adapté.", "groups": [{"position": 1, "keywords": ["présence rassurante", "effet apaisant", "attente du soutien"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment organisez-vous la suite de cette prise en charge, au-delà de ce seul contrôle routier initial ?", "hint": "La transformation de ce contrôle en une problématique de détresse nécessite une prise en charge structurée qui dépasse le seul cadre de cette interpellation ponctuelle.", "perfect": "Je m''assure qu''un accompagnement adapté à sa détresse psychologique soit mis en place, cette prise en charge dépassant largement le seul cadre de ce contrôle routier qui n''était initialement pas destiné à traiter cette problématique.\n\nJe reste attentive à ce que cette prise en charge n''ait pas un caractère stigmatisant pour lui, cette détresse méritant une réponse bienveillante plutôt qu''un traitement qui le renverrait à un sentiment de honte supplémentaire.\n\nJe consigne avec précision les circonstances de cette confidence et de la prise en charge engagée, ces éléments pouvant être utiles pour la suite du suivi de sa situation par les services compétents.\n\nJe reste attentive à ce que son véhicule et sa situation matérielle immédiate soient également pris en compte, cette dimension pratique ne devant pas être négligée au profit de la seule dimension psychologique de cette situation.", "points": [{"position": 1, "label": "S''assurer d''un accompagnement adapté dépassant le cadre routier initial", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : prise en charge dépassant le contrôle ponctuel.", "groups": [{"position": 1, "keywords": ["accompagnement adapté", "au-delà du contrôle routier", "prise en charge structurée"]}]}, {"position": 2, "label": "Veiller à ce que la prise en charge ne soit pas stigmatisante", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Réponse bienveillante plutôt qu''un sentiment de honte.", "groups": [{"position": 1, "keywords": ["pas stigmatisant", "bienveillance", "pas de honte supplémentaire"]}]}, {"position": 3, "label": "Consigner précisément les circonstances pour le suivi ultérieur", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Utile pour les services compétents.", "groups": [{"position": 1, "keywords": ["circonstances consignées", "suivi ultérieur", "services compétents"]}]}, {"position": 4, "label": "Prendre en compte la dimension matérielle de son véhicule et sa situation", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Ne pas négliger cette dimension pratique.", "groups": [{"position": 1, "keywords": ["dimension matérielle", "véhicule pris en compte", "pas négligée"]}]}]}]}'::jsonb);